package net.minecraft.core.registries;import net.minecraft.world.item.*;import net.minecraft.resources.*;import java.util.*;public class BuiltInRegistries {public static final Items ITEM=new Items();public static class Items {public final Map<String,Item> registered=new HashMap<>();public Items(){register("minecraft:charcoal");register("minecraft:coal");register("minecraft:stick");register("minecraft:torch");register("minecraft:crafting_table");}public Item register(String name){Item obj=new Item(name);registered.put(name,obj);return obj;}public boolean containsKey(ResourceLocation r){return registered.containsKey(r.toString());}public ResourceLocation getKey(Item item){return new ResourceLocation(item.id);}public Item get(String name){return registered.get(name);}}}